'use client';

import { motion } from 'motion/react';

export interface TrashIconBounceProps {
  size?: number;
  color?: string;
  className?: string;
  isAnimating?: boolean;
}

export function TrashIconBounce({
  size = 24,
  color = 'currentColor',
  className = '',
  isAnimating = false
}: TrashIconBounceProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke={color}
      strokeWidth={2}
      strokeLinecap="round"
      strokeLinejoin="round"
      className={className}
    >
      {/* Static lid */}
      <path d="M4 7h16" />

      {/* Animated vertical lines - fill up effect */}
      <motion.path
        d="M10 11v6"
        animate={isAnimating ? "filling" : "idle"}
        variants={{
          idle: {
            strokeDasharray: "0 6",
            strokeDashoffset: 0,
            opacity: 1
          },
          filling: {
            strokeDasharray: ["0 6", "6 0", "6 0", "0 6"],
            strokeDashoffset: [0, 0, 0, 0],
            opacity: [1, 1, 0.3, 0],
            transition: {
              duration: 1.2,
              times: [0, 0.4, 0.7, 1],
              repeat: Infinity,
              ease: "easeInOut"
            }
          }
        }}
      />

      <motion.path
        d="M14 11v6"
        animate={isAnimating ? "filling" : "idle"}
        variants={{
          idle: {
            strokeDasharray: "0 6",
            strokeDashoffset: 0,
            opacity: 1
          },
          filling: {
            strokeDasharray: ["0 6", "6 0", "6 0", "0 6"],
            strokeDashoffset: [0, 0, 0, 0],
            opacity: [1, 1, 0.3, 0],
            transition: {
              duration: 1.2,
              times: [0, 0.4, 0.7, 1],
              repeat: Infinity,
              ease: "easeInOut"
            }
          }
        }}
      />

      {/* Animated trash body - crush effect */}
      <motion.g
        style={{
          transformBox: 'fill-box',
          transformOrigin: 'center bottom'
        }}
        animate={isAnimating ? "crushing" : "idle"}
        variants={{
          idle: {
            scaleY: 1,
            transition: {
              type: "spring",
              stiffness: 300,
              damping: 20
            }
          },
          crushing: {
            scaleY: [1, 0.85, 1],
            transition: {
              duration: 1.2,
              times: [0, 0.5, 1],
              repeat: Infinity,
              ease: "easeInOut"
            }
          }
        }}
      >
        <path d="M5 7l1 12a2 2 0 0 0 2 2h8a2 2 0 0 0 2 -2l1 -12" />
        <path d="M9 7v-3a1 1 0 0 1 1 -1h4a1 1 0 0 1 1 1v3" />
      </motion.g>
    </svg>
  );
}
